using System;
using System.Linq;
using Beamable.Api.Autogenerated.Models;
using Beamable.Common.BeamCli.Contracts;
using Beamable.Common.Content;

namespace cli.BundleCommands;

/// <summary>
/// Maps a bundle's tags onto the <see cref="BundleTagInfo"/> contract. The mapping lives in the
/// CLI because the contract assembly copies (Unity/Unreal) don't ship the autogenerated API
/// models. Tags point at versions.
/// </summary>
public static class BundleTagInfoExtensions
{
	public static BundleTagInfo[] ToTagInfos(this OptionalMapOfLong tags)
	{
		var map = tags?.GetOrElse(new MapOfLong()) ?? new MapOfLong();
		return map
			.OrderBy(kvp => kvp.Key, StringComparer.Ordinal)
			.Select(kvp => new BundleTagInfo { tag = kvp.Key, version = kvp.Value })
			.ToArray();
	}
}
